<script setup lang="ts">
import {uiError,uiErrorMessage} from '../module-localization.ts';
import {uiMessage,joinMessages} from '../module-localization.ts';
import {tr,messageRef} from '../../i18n/index.ts';
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import ResearchUpload from '../../components/ResearchUpload.vue';
import AppIcon from '../../components/AppIcon.vue';
import ModuleWorkbench from '../../components/ModuleWorkbench.vue';
import ModuleFrame from '../../components/ModuleFrame.vue';
import ModuleToolbar from '../../components/ModuleToolbar.vue';
import ModuleStatus from '../../components/ModuleStatus.vue';
import {computed,ref,shallowRef,reactive,watch,onMounted,onUnmounted,markRaw,nextTick} from 'vue';
import {audioPreview,type ResearchContext,type ResearchFile,type JobView,type Tier,type SpectrogramView} from '../../platform/research.ts';
import {host,workspace,type Workspace} from '../../state/workspace.ts';
import {stop} from '../../state/audio.ts';import {decodeWav} from '../../platform/decode.ts';import {exportFontSnapshot} from '../../state/fonts.ts';
import WaveformViewport from '../../components/WaveformViewport.vue';import AudioTransport from '../../components/AudioTransport.vue';import TaskPanel from '../../components/TaskPanel.vue';
import TextGridTimeline from '../../components/TextGridTimeline.vue';
import SpectrumPlot from './SpectrumPlot.vue';
import {axisLimits} from './display.ts';import {spectrumPng} from './export.ts';import {downloadPng} from '../../design/plot-export.ts';
import {restoreDraft,parameters,configuration,visibleRange,parseResult,sameAnalysis,jobError,jobErrorMessage,audioSelection,gridRangeStatus,type LpcResult} from './state.ts';

const props=defineProps<{context:ResearchContext;stateKey:string;active:boolean}>();const emit=defineEmits<{references:[];help:[];close:[]}>();
const wave=workspace(props.stateKey),draft=ref(restoreDraft(host.projects.read('lpc.config.'+props.stateKey,null)));
const showSpectrum=ref(host.projects.read<boolean>('lpc.showSpectrum.'+props.stateKey,false)===true);
watch(showSpectrum,value=>host.projects.write('lpc.showSpectrum.'+props.stateKey,value));
function toggleSpectrum(){const enable=mode.value!=='spectrum'||!showSpectrum.value;if(enable&&!result.value?.reference_spectrum){notice.value=uiMessage('modules.lpc-spectrum.this_historical_result_has_no_fft_spectrum_reanalyse_to');return;}showSpectrum.value=enable;mode.value='spectrum';}
const resultWave=reactive<Workspace>({...wave,asset:null,dirty:false});
const playbackState=computed(()=>mode.value==='spectrum'&&!wave.asset?resultWave:wave);
const transportRef=ref<{selectAll:(autoplay?:boolean)=>Promise<void>}|null>(null);
const files=ref<ResearchFile[]>([]),source=ref<ResearchFile>(),grid=ref<ResearchFile|null>(null),tiers=ref<Tier[]>([]),tier=ref(''),directory=ref('');
const picker=ref<HTMLInputElement>(),mode=ref<'wave'|'spectrum'>('wave'),selected=ref(false),start=ref('0'),end=ref('0');
const error=messageRef(''),notice=messageRef(''),loading=ref(false),gridLoading=ref(false),submitting=ref(false),reading=ref(false),saving=ref(false),savingImage=ref(false),cancelPending=ref(false);
const jobs=ref<JobView[]>([]),current=ref<JobView>(),resultJob=ref<JobView>(),result=shallowRef<LpcResult>();
const tasks=computed(()=>props.context.files.tasks),audioFiles=computed(()=>files.value.filter(f=>f.kind==='audio')),grids=computed(()=>files.value.filter(f=>f.kind==='textgrid'));
const spectrogramLoader=computed(()=>{const file=source.value;return file&&props.context.files.spectrogram?(view:SpectrogramView)=>props.context.files.spectrogram!(file,view):undefined;});
let disposed=false,fileEpoch=0,gridEpoch=0,resultEpoch=0,listEpoch=0,submitEpoch=0,abort:AbortController|undefined,polling=false;
let submittedJobId:string|undefined;
watch(draft,()=>wave.dirty=true,{deep:true});
function save(){error.value='';try{parameters(draft.value);if(!host.projects.write('lpc.config.'+props.stateKey,{...draft.value}))throw uiError(uiMessage('modules.lpc-spectrum.failed_to_save_parameter_draft_check_local_storage_permissions'));wave.dirty=false;notice.value=uiMessage('modules.lpc-spectrum.lpc_parameter_draft_saved');return true;}catch(e){error.value=errorText(e);return false;}}
defineExpose({save});
const viewRange=computed(()=>visibleRange(wave.asset?.duration??0,wave.zoom,wave.offset));
watch(()=>[wave.start,wave.end],([a,b])=>{start.value=String(a);end.value=String(b);selected.value=true;},{flush:'sync'});
watch(viewRange,()=>{if(!selected.value)clearSelection();});
function clearSelection(){stop();[wave.start,wave.end]=viewRange.value;start.value=String(wave.start);end.value=String(wave.end);selected.value=false;}
function selectRange(a:number,b:number){stop();const range=audioSelection(a,b,wave.asset?.duration??0);if(!range){wave.start=Number(start.value);wave.end=Number(end.value);return;}selected.value=true;[a,b]=range;start.value=String(a);end.value=String(b);wave.start=a;wave.end=b;}
const gridRange=computed(()=>wave.asset?gridRangeStatus(tiers.value,wave.asset.duration,wave.asset.sampleRate):'valid');
const validation=computed(()=>{try{if(!wave.asset||!source.value)return {error:tr('modules.lpc-spectrum.select_wav_audio_first')};if(draft.value.analysis_channel!=null&&draft.value.analysis_channel!=='mean'&&Number(draft.value.analysis_channel)>=wave.asset.channels.length)return {error:tr('modules.lpc-spectrum.the_selected_analysis_channel_does_not_exist_select_again')};if(gridLoading.value)return {error:tr('modules.lpc-spectrum.reading_textgrid')};if(grid.value&&!tier.value)return {error:tr('modules.lpc-spectrum.select_a_valid_textgrid_tier')};if(gridRange.value==='mismatch')return {error:jobError('lpc_textgrid_range')};return {config:configuration(draft.value,start.value,end.value,wave.asset.sampleRate,wave.asset.frames,grid.value?tier.value:null,exportFontSnapshot()),error:''};}catch(e){return {error:jobError(e instanceof Error?e.message:String(e))};}});
const stale=computed(()=>!!result.value&&(!validation.value.config||!sameAnalysis(result.value,validation.value.config,source.value?.sha256??'',grid.value?.sha256??null)));
const liveJob=computed(()=>current.value&&['queued','running','cancel_requested'].includes(current.value.state));
const taskViews=computed(()=>jobs.value.map(j=>({id:j.id,title:`LPC · ${new Date(j.created_at*1000).toLocaleTimeString()} · ${j.execution==='browser'?tr('modules.lpc-spectrum.browser'):''}${j.id.slice(0,8)}`,status:j.state,error:j.error_code?jobError(j.error_code):undefined,canCancel:true,canRetry:true})));
const display=computed(()=>{if(!result.value)return;try{return {y:axisLimits(result.value,draft.value.dynamic_y,draft.value.amp_min_db,draft.value.amp_max_db),error:''};}catch(e){return {y:[result.value.spectrum.amp_min_db,result.value.spectrum.amp_max_db] as [number,number],error:jobError(e instanceof Error?e.message:String(e))};}});
function errorText(e:unknown){return jobErrorMessage(e);}
function clearResult(){++resultEpoch;reading.value=false;result.value=undefined;resultJob.value=undefined;resultWave.asset=null;current.value=undefined;mode.value='wave';stop();}
async function refresh(){const ticket=++listEpoch;try{const list=await props.context.files.list(directory.value||undefined);if(disposed||ticket!==listEpoch)return;files.value=list;
  if(source.value){const next=list.find(f=>f.id===source.value!.id);if(!next||next.size!==source.value.size||(next.sha256&&next.sha256!==source.value.sha256)){++fileEpoch;++gridEpoch;abort?.abort();source.value=undefined;wave.asset=null;grid.value=null;tiers.value=[];tier.value='';loading.value=false;gridLoading.value=false;clearResult();notice.value=uiMessage('modules.lpc-spectrum.original_audio_was_removed_or_changed_select_it_again');}}
  if(grid.value){const next=list.find(f=>f.id===grid.value!.id);if(!next||next.size!==grid.value.size||(next.sha256&&next.sha256!==grid.value.sha256)){++gridEpoch;grid.value=null;tiers.value=[];tier.value='';gridLoading.value=false;notice.value=uiMessage('modules.lpc-spectrum.original_textgrid_was_removed_or_changed_link_it_again');}}
 }catch(e){if(!disposed&&ticket===listEpoch)error.value=errorText(e);}}
async function choose(){try{const grant=await props.context.files.choose?.('input');if(grant&&!disposed){directory.value=grant.id;await refresh();}}catch(e){if(!disposed)error.value=errorText(e);}}
function addFiles(event:Event){props.context.files.add?.([...((event.target as HTMLInputElement).files??[])]);void refresh();(event.target as HTMLInputElement).value='';}
async function associate(id:string){const ticket=++gridEpoch,fileTicket=fileEpoch;grid.value=grids.value.find(f=>f.id===id)??null;tiers.value=[];tier.value='';error.value='';if(!grid.value){gridLoading.value=false;return;}const file=grid.value;gridLoading.value=true;
  try{const data=await props.context.files.textgrid(file);if(disposed||ticket!==gridEpoch||fileTicket!==fileEpoch)return;grid.value={...file,sha256:data.sha256};tiers.value=data.tiers;tier.value=data.tiers[0]?.name??'';if(!tier.value)throw uiError(uiMessage('modules.lpc-spectrum.textgrid_has_no_usable_tiers'));}catch(e){if(!disposed&&ticket===gridEpoch&&fileTicket===fileEpoch)error.value=errorText(e);}finally{if(ticket===gridEpoch)gridLoading.value=false;}}
async function load(id:string){const file=audioFiles.value.find(f=>f.id===id);if(!file)return;const ticket=++fileEpoch;++gridEpoch;abort?.abort();abort=new AbortController();source.value=file;grid.value=null;tiers.value=[];tier.value='';gridLoading.value=false;clearResult();wave.asset=null;selected.value=false;loading.value=true;error.value='';notice.value='';
  try{if(file.size>64_000_000)throw Error('lpc_input_budget');const data=await audioPreview(props.context.files,file,abort.signal);if(disposed||ticket!==fileEpoch)return;const a=data.asset;if(a.frames>8_000_000||a.channels.length>8)throw Error('lpc_input_budget');if(a.sampleRate<8000||a.sampleRate>96000)throw Error('lpc_sample_rate');source.value={...file,sha256:data.sha256};wave.asset=markRaw(a);wave.zoom=1;wave.offset=0;wave.channel=0;clearSelection();const same=grids.value.filter(f=>f.name.replace(/\.TextGrid$/i,'').toLowerCase()===file.name.replace(/\.wav$/i,'').toLowerCase());if(same.length===1)await associate(same[0].id);
  }catch(e){if(!disposed&&ticket===fileEpoch)error.value=errorText(e);}finally{if(ticket===fileEpoch)loading.value=false;}}
async function show(job:JobView){if(job.state!=='succeeded'||job.result_manifest?.kind!=='managed_lpc_files'||!tasks.value?.result)return;current.value=job;const ticket=++resultEpoch;reading.value=true;error.value='';notice.value='';stop();
  try{const entries=job.result_manifest.files,json=entries.find(f=>f.name==='lpc.ptb.json')!;
    const raw=await tasks.value.result(job.id,json.id,json.sha256);if(disposed||ticket!==resultEpoch)return;const data=parseResult(raw);
    const recoveringClip=!wave.asset;
    if(recoveringClip){
      const audio=entries.find(f=>f.name==='lpc_AUDIO.wav');if(!audio)throw uiError(uiMessage('modules.lpc-spectrum.historical_result_has_no_playback_audio'));
      const wav=await tasks.value.result(job.id,audio.id,audio.sha256);if(disposed||ticket!==resultEpoch)return;
      const asset=await decodeWav(wav,audio.name);if(disposed||ticket!==resultEpoch)return;
      resultWave.asset=markRaw(asset);resultWave.start=0;resultWave.end=asset.duration;resultWave.channel=0;
    }
    result.value=data;resultJob.value=job;mode.value='spectrum';
    if(recoveringClip){
      await nextTick();
      if(!disposed&&ticket===resultEpoch)await transportRef.value?.selectAll();
    }
  }catch(e){if(!disposed&&ticket===resultEpoch)error.value=errorText(e);}finally{if(ticket===resultEpoch)reading.value=false;}}
async function poll(){if(polling||disposed||!tasks.value?.lpcJobs)return;polling=true;try{const data=await tasks.value.lpcJobs();if(disposed)return;jobs.value=data;const old=current.value;if(old){const next=data.find(j=>j.id===old.id);if(next){current.value=next;if(old.state!=='succeeded'&&next.state==='succeeded')await show(next);}}}catch(e){if(!disposed)error.value=errorText(e);}finally{polling=false;}}
async function submit(){if(!source.value||!tasks.value?.lpc||submitting.value)return;const frozen=validation.value.config;if(!frozen){error.value=validation.value.error;return;}const ticket=++submitEpoch,fileTicket=fileEpoch,file={...source.value},textgrid=grid.value?{...grid.value}:null;submitting.value=true;cancelPending.value=false;error.value='';notice.value='';
  try{if(!tasks.value.lpcFonts)throw uiError(uiMessage('modules.lpc-spectrum.this_entry_cannot_check_lpc_export_fonts_restart_the'));const fonts=await tasks.value.lpcFonts(frozen.font!);if(disposed||ticket!==submitEpoch||cancelPending.value||fileTicket!==fileEpoch)return;
    if(!fonts.available)throw uiError(joinMessages(joinMessages(uiMessage('modules.lpc-spectrum.fonts_missing_from_export_environment'),fonts.fonts.filter(f=>!f.available).map(f=>f.requested).join('、')),uiMessage('modules.lpc-spectrum.adjust_plot_fonts_in_settings')));
    const job=await tasks.value.lpc(file,textgrid,frozen,crypto.randomUUID());submittedJobId=job.id;
    if(disposed||ticket!==submitEpoch||cancelPending.value){if(tasks.value.cancelJob)await tasks.value.cancelJob(job.id);return;}
    if(fileTicket!==fileEpoch)return;current.value=job;if(job.state==='succeeded')await show(job);await poll();
  }catch(e){if(!disposed&&ticket===submitEpoch&&fileTicket===fileEpoch)error.value=errorText(e);}finally{if(ticket===submitEpoch){submitting.value=false;cancelPending.value=false;submittedJobId=undefined;}}}
async function cancel(id?:string){if(submitting.value&&!id&&!submittedJobId){cancelPending.value=true;notice.value=uiMessage('modules.lpc-spectrum.cancellation_requested_the_background_task_will_be_cancelled_after');return;}const target=id??(submitting.value?submittedJobId:current.value?.id);if(!target)return;try{await tasks.value?.cancelJob?.(target);await poll();}catch(e){if(!disposed)error.value=errorText(e);}}
async function retry(id:string){if(submitting.value)return;const ticket=++submitEpoch,fileTicket=fileEpoch;submitting.value=true;cancelPending.value=false;try{const job=await tasks.value!.retry(id,crypto.randomUUID());submittedJobId=job.id;if(disposed||cancelPending.value){await tasks.value?.cancelJob?.(job.id);return;}if(fileTicket===fileEpoch){current.value=job;if(job.state==='succeeded')await show(job);}await poll();}catch(e){if(!disposed&&ticket===submitEpoch&&fileTicket===fileEpoch)error.value=errorText(e);}finally{if(ticket===submitEpoch){submitting.value=false;cancelPending.value=false;submittedJobId=undefined;}}}
async function saveResult(){const job=resultJob.value,ticket=resultEpoch;if(!job||saving.value)return;saving.value=true;error.value='';notice.value='';try{const grant=await props.context.files.choose?.('output');if(!grant||disposed||ticket!==resultEpoch)return;const saved=await tasks.value!.saveJob!(job.id,grant.id);if(!disposed&&ticket===resultEpoch)notice.value=uiMessage('modules.lpc-spectrum.saved_value_result_files_same_name_files_with_different',{v0:(saved.count)});}catch(e){if(!disposed&&ticket===resultEpoch)error.value=errorText(e);}finally{saving.value=false;}}
async function saveImage(){
 const job=resultJob.value,data=result.value,ticket=resultEpoch;if(!job||!data||savingImage.value)return;
 savingImage.value=true;error.value='';notice.value='';
 try{
  if(job.result_manifest?.kind!=='managed_lpc_files')throw uiError(uiMessage('modules.lpc-spectrum.this_result_cannot_save_png_yet_reopen_the_task'));
  const file=job.result_manifest.files.find(f=>f.name.toLowerCase().endsWith('.png'));
  if(!file)throw uiError(uiMessage('modules.lpc-spectrum.this_task_has_no_png_image_reanalyse'));
  const y=axisLimits(data,draft.value.dynamic_y,draft.value.amp_min_db,draft.value.amp_max_db);
  const image=await spectrumPng(data,y,showSpectrum.value);if(disposed||ticket!==resultEpoch)return;
  downloadPng(image,data.export_names[file.name]??file.name);
  notice.value=props.context.files.kind==='desktop'?uiMessage('modules.lpc-spectrum.png_save_dialog_opened_choose_a_location_or_cancel'):uiMessage('modules.lpc-spectrum.png_image_sent_to_browser_for_download');
 }catch(e){if(!disposed&&ticket===resultEpoch)error.value=errorText(e);}finally{savingImage.value=false;}
}
async function download(id:string,name:string){if(name.toLowerCase().endsWith('.png'))return saveImage();const ticket=resultEpoch;try{await tasks.value?.download?.(id,name);if(!disposed&&ticket===resultEpoch)notice.value=joinMessages(uiMessage('modules.lpc-spectrum.sent_to_browser_for_download'),name);}catch(e){if(!disposed&&ticket===resultEpoch)error.value=errorText(e);}}
watch(()=>props.active,active=>{if(!active)stop();else void poll();});watch(mode,()=>stop());
onMounted(()=>{if(props.context.files.kind!=='desktop')void refresh();void poll();});const timer=setInterval(()=>{if(props.active!==false||submitting.value||jobs.value.some(j=>['queued','running','cancel_requested'].includes(j.state)))void poll();},1500);
onUnmounted(()=>{disposed=true;++fileEpoch;++gridEpoch;++resultEpoch;++listEpoch;abort?.abort();clearInterval(timer);stop();});
useWebSettings(props.stateKey,{draft,showSpectrum,...settingsFields(wave,['showBoth','showSpectrogram'])},undefined,()=>wave.dirty=false);
</script>

<template><ModuleFrame unified fit :label="tr('modules.lpc-spectrum.lpc_spectrum_workspace')" class="workspace-page lpc-page">
<template #toolbar><ModuleToolbar><ResearchUpload :files="context.files" accept=".wav,.TextGrid" @uploaded="refresh"/><button class="primary" v-if="context.files.choose" @click="choose"><AppIcon name="folder"/>{{tr('modules.lpc-spectrum.open_audio_folder')}}</button><template v-if="context.files.add"><input ref="picker" type="file" accept=".wav,.TextGrid" multiple hidden @change="addFiles"/><button class="primary" @click="picker?.click()">{{tr('modules.lpc-spectrum.import_files')}}</button></template><button @click="refresh">{{tr('modules.lpc-spectrum.refresh_files')}}</button><template #actions><button @click="save">{{tr('modules.lpc-spectrum.save_parameter_draft')}}</button><button type="button" data-action="module-help" @click="emit('help')">{{tr('modules.lpc-spectrum.help')}}</button><button @click="emit('references')"><AppIcon name="book"/>{{tr('modules.lpc-spectrum.methods_and_references')}}</button></template></ModuleToolbar></template>
<ModuleWorkbench unified :state-key="stateKey" :left-label="tr('modules.lpc-spectrum.files_and_playback')" :right-label="tr('modules.lpc-spectrum.tasks_and_records')"><template #left><div class="lpc-files workbench-card">

<label class="field">{{tr('modules.lpc-spectrum.audio_files')}}<select :aria-label="tr('modules.lpc-spectrum.lpc_audio_files')" :value="source?.id??''" @change="load(($event.target as HTMLSelectElement).value)"><option disabled value="">{{tr('modules.lpc-spectrum.select_wav')}}</option><option v-for="file in audioFiles" :key="file.id" :value="file.id">{{file.name}}</option></select></label>
<small v-if="wave.asset">{{tr('modules.lpc-spectrum.audioInfo',{sampleRate:wave.asset.sampleRate,channels:wave.asset.channels.length,duration:wave.asset.duration.toFixed(3)})}}</small><ModuleStatus v-if="loading" kind="loading" :message="tr('modules.lpc-spectrum.reading_audio')"/>
<label class="field">{{tr('modules.lpc-spectrum.link_textgrid')}}<select aria-label="LPC TextGrid" :value="grid?.id??''" :disabled="!wave.asset" @change="associate(($event.target as HTMLSelectElement).value)"><option value="">{{tr('modules.lpc-spectrum.no_association')}}</option><option v-for="file in grids" :key="file.id" :value="file.id">{{file.name}}</option></select></label>
<label class="field">{{tr('modules.lpc-spectrum.annotation_tier')}}<select v-model="tier" :aria-label="tr('modules.lpc-spectrum.lpc_annotation_tier')" :disabled="!tiers.length||gridLoading"><option v-if="!tiers.length" value="">{{tr('modules.lpc-spectrum.no_annotation')}}</option><option v-for="t in tiers" :key="t.name" :value="t.name">{{t.name}}</option></select></label><button :disabled="tiers.length<2" @click="tier=tiers[(tiers.findIndex(t=>t.name===tier)+1)%tiers.length].name">{{tr('modules.lpc-spectrum.next_tier')}}</button>
<small class="file-hint">{{tr('modules.lpc-spectrum.automatically_link_same_name_textgrid')}}</small>
<label v-if="wave.asset" class="field">{{tr('modules.lpc-spectrum.analysis_channel')}}<select v-model="draft.analysis_channel" :aria-label="tr('modules.lpc-spectrum.lpc_analysis_channel')"><option value="mean">{{tr('modules.lpc-spectrum.multichannel_mean_original_method')}}</option><option v-for="(_,i) in wave.asset.channels" :key="i" :value="String(i)">{{tr('modules.lpc-spectrum.channel')}} {{i+1}}</option></select></label>
<small v-if="gridRange==='blank-overhang'" class="grid-notice">{{tr('modules.lpc-spectrum.blank_textgrid_intervals_extend_beyond_the_audio_selection_is')}}</small>
<label v-if="wave.asset&&wave.asset.channels.length>1" class="field">{{tr('modules.lpc-spectrum.playback_channel')}}<select v-model.number="wave.channel" @change="stop"><option v-for="(_,i) in wave.asset.channels" :key="i" :value="i">{{tr('modules.lpc-spectrum.channel')}} {{i+1}}</option></select></label>
</div><section class="lpc-card lpc-analysis-settings"><div class="control-row"><strong>{{tr('modules.lpc-spectrum.spectrum_parameters')}}</strong><small v-if="wave.dirty">{{tr('modules.lpc-spectrum.parameters_not_saved')}}</small><label>{{tr('modules.lpc-spectrum.order')}}<input v-model="draft.order" :aria-label="tr('modules.lpc-spectrum.lpc_order')" type="number" min="1" max="200"/></label><label>{{tr('modules.lpc-spectrum.maximum_frequency_hz')}}<input v-model="draft.freq_max_hz" :aria-label="tr('modules.lpc-spectrum.lpc_maximum_frequency')" type="number" min="100" max="48000"/></label><label>{{tr('modules.lpc-spectrum.minimum_db')}}<input v-model="draft.amp_min_db" :aria-label="tr('modules.lpc-spectrum.lpc_minimum_amplitude')" :disabled="draft.dynamic_y" type="number" min="-200" max="100"/></label><label>{{tr('modules.lpc-spectrum.maximum')}}<input v-model="draft.amp_max_db" :aria-label="tr('modules.lpc-spectrum.lpc_maximum_amplitude')" :disabled="draft.dynamic_y" type="number" min="-200" max="100"/></label><small v-if="draft.dynamic_y">{{tr('modules.lpc-spectrum.automatically_add_5_db_padding_around_spectral_values_in')}}</small></div><p v-if="!tasks?.lpc" class="muted">{{tr('modules.lpc-spectrum.wav_preview_is_available_here_for_computation_use_a')}}</p>
</section></template>

<section class="lpc-card"><div class="view-tabs" :aria-label="tr('modules.lpc-spectrum.lpc_display_mode')"><button :aria-pressed="mode==='wave'" @click="mode='wave'">{{tr('modules.lpc-spectrum.waveform')}}</button><button :aria-pressed="mode==='spectrum'" :disabled="!result" @click="mode='spectrum'">{{tr('modules.lpc-spectrum.lpc_spectrum')}}</button><button :aria-pressed="showSpectrum&&mode==='spectrum'" :disabled="!result" @click="toggleSpectrum">{{tr('modules.lpc-spectrum.show_spectrum')}}</button><label v-if="wave.asset"><input v-model="wave.showSpectrogram" type="checkbox" :disabled="!context.files.spectrogram"/>{{tr('modules.lpc-spectrum.show_spectrogram_praat')}}</label><span v-if="reading" role="status">{{tr('modules.lpc-spectrum.reading_results')}}</span></div>
<div v-show="mode==='wave'"><WaveformViewport :empty-message="tr('modules.lpc-spectrum.select_wav_to_show_the_original_waveform_drag_with')" :state="wave" :spectrogram-loader="spectrogramLoader" spectrogram-selectable compact-overview @selection-end="selectRange"><template #timeline="{start:a,end:b}"><TextGridTimeline v-if="tier" :state="wave" :tiers="tiers.filter(t=>t.name===tier)" :start="a" :end="b" :selected="0" :selection-start="wave.start" :selection-end="wave.end" :selected-tier-label="tr('modules.lpc-spectrum.current_annotation_tier')" @select="(_i,s,e)=>selectRange(s,e)"/></template></WaveformViewport></div>
<SpectrumPlot v-if="result&&display" v-show="mode==='spectrum'" :result="result" :y="display.y" :dynamic="draft.dynamic_y" :show-spectrum="showSpectrum" @axis-mode="draft.dynamic_y=$event"/><p v-if="display?.error" role="alert" class="error-text">{{display.error}}</p>
<p v-if="result&&mode==='spectrum'" class="muted">{{result.input_name}} · {{result.selection.start_s.toFixed(6)}}–{{result.selection.end_s.toFixed(6)}} s · {{result.selection.end_sample-result.selection.start_sample}} {{tr('modules.lpc-spectrum.samples')}} {{result.config.order}} {{tr('modules.lpc-spectrum.order_75')}} {{result.config.analysis_channel==null?tr('modules.lpc-spectrum.multichannel_mean'):tr('modules.lpc-spectrum.analysis_channel_77')+(result.config.analysis_channel+1)}}</p>
<small v-if="result?.reference_spectrum&&showSpectrum&&mode==='spectrum'" class="muted">{{tr('modules.lpc-spectrum.fft_and_lpc_use_the_same_segment_0_97')}}</small>
