</section>

<template #right><section class="lpc-card lpc-run"><strong>{{tr('modules.lpc-spectrum.analysis_and_export')}}</strong><div class="control-row"><button class="primary" :disabled="loading||gridLoading||submitting||!!liveJob||!tasks?.lpc||!wave.asset" @click="submit">{{submitting?tr('modules.lpc-spectrum.submitting'):tr('modules.lpc-spectrum.start_analysis')}}</button><button v-if="submitting||liveJob" :disabled="cancelPending" @click="cancel()">{{tr('modules.lpc-spectrum.cancel_analysis')}}</button><small v-if="validation.error" class="muted">{{validation.error}}</small><small v-else>{{tr('modules.lpc-spectrum.up_to_48_000_samples_per_run_1024_point')}}</small></div></section><ModuleStatus v-if="error" kind="error" :message="error"/><ModuleStatus v-if="notice" :message="notice"/><section v-if="result&&resultJob" class="lpc-card lpc-results"><div class="control-row"><strong>{{tr('modules.lpc-spectrum.save_results')}}</strong><button class="primary" :disabled="savingImage||reading||!!display?.error" @click="saveImage">{{savingImage?tr('modules.lpc-spectrum.generating_png'):tr('modules.lpc-spectrum.save_png_image')}}</button><button class="primary" v-if="tasks?.saveJob" :disabled="saving||reading" @click="saveResult">{{tr('modules.lpc-spectrum.select_folder_to_save_complete_results')}}</button><template v-if="tasks?.download&&resultJob.result_manifest?.kind==='managed_lpc_files'"><button v-for="file in resultJob.result_manifest.files" :key="file.id" @click="download(file.id,result!.export_names[file.name]??file.name)">{{tr('modules.lpc-spectrum.download')}} {{file.name.endsWith('.png')?'PNG':file.name.endsWith('.wav')?tr('modules.lpc-spectrum.selection_wav'):tr('modules.lpc-spectrum.parameters_and_spectral_values_json')}}</button></template></div><small>{{tr('modules.lpc-spectrum.png_uses_the_current_vertical_axis_a_white_background')}}</small><details><summary>{{tr('modules.lpc-spectrum.view_parameter_snapshot_for_this_result')}}</summary><pre>{{JSON.stringify(result.config,null,2)}}</pre></details></section>
<details class="lpc-card lpc-history" open><summary>{{tr('modules.lpc-spectrum.historyCount',{count:jobs.length})}}</summary><TaskPanel :tasks="taskViews" :empty-text="tr('modules.lpc-spectrum.select_a_short_audio_segment_and_start_analysis_results')" @cancel="cancel" @retry="retry"/><div class="history-links"><button v-for="job in jobs.filter(j=>j.state==='succeeded')" :key="job.id" @click="show(job)">{{tr('modules.lpc-spectrum.view_results')}} {{new Date(job.created_at*1000).toLocaleTimeString()}} · {{job.id.slice(0,8)}}</button></div></details>
</template></ModuleWorkbench><div class="lpc-transport global-transport"><AudioTransport ref="transportRef" :state="playbackState" :active="active"/></div></ModuleFrame></template>
